namespace Erlang.Differential;

public static class ListLengthCaseSources
{
    public const string ComprehensionFilters = "-module(length_comprehension_filters).\n-export([run/0]).\nrun() ->\n    L = make(32001,[]),\n    [yes] = [yes || X <- [L,[a|tail],[]], length(X) =:= 32001],\n    <<1>> = << <<1>> || X <- [L,[a|tail],[]], length(X) =:= 32001 >>,\n    #{yes := 32001} = #{yes => length(X) || X <- [L,[a|tail],[]], length(X) =:= 32001},\n    done.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string DynamicPatterns = "-module(length_dynamic_patterns).\n-export([run/0]).\nrun() ->\n    L = make(32001,[]),\n    Map = #{32001 => payload},\n    #{(length(L)) := V} = Map,\n    payload = V,\n    Bits = <<0:32001,7:3>>,\n    <<_:(length(L)),Tail/bitstring>> = Bits,\n    <<7:3>> = Tail,\n    Sequential = <<3:8,0:32001,7:3>>,\n    <<Count:8,_:(length(L)),Last:Count>> = Sequential,\n    3 = Count,\n    7 = Last,\n    {fallback,tag} = choose({tag,#{}},[a|tail]),\n    done.\nchoose(Value,L) -> case Value of {A,#{(length(L)) := B}} -> {A,B}; {C,_} -> {fallback,C} end.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string GuardContexts = "-module(length_guard_contexts).\n-export([run/0]).\nrun() ->\n    L = make(32001,[]),\n    good = choose(L),\n    bad = choose([a|tail]),\n    good = case L of X when length(X) =:= 32001 -> good end,\n    good = if length(L) =:= 32001 -> good; true -> bad end,\n    good = alternatives([a|tail]),\n    false = (false andalso length([a|tail])),\n    true = (true orelse length([a|tail])),\n    done.\nchoose(X) when length(X) =:= 32001 -> good;\nchoose(_) -> bad.\nalternatives(X) when length(X) > 0; is_list(X) -> good;\nalternatives(_) -> bad.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string LongBadarg = "-module(length_long_badarg).\n-export([run/0]).\nrun() ->\n    Original = make(64001,tail),\n    true = try apply(erlang,length,[Original]) of _ -> false catch error:badarg:Stack -> [{erlang,length,[Argument],_}|_] = Stack, Argument =:= Original end,\n    fallback = guarded(Original),\n    done.\nguarded(X) when length(X) > 0 -> wrong;\nguarded(_) -> fallback.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string Matchspec = "-module(length_matchspec).\n-export([run/0]).\nrun() ->\n    L = make(64017,[]),\n    {ok,64017,[],[]} = erlang:match_spec_test({L},[{{'$1'},[],[{length,'$1'}]}],table),\n    {ok,false,[],[]} = erlang:match_spec_test({[a|tail]},[{{'$1'},[{'>',{length,'$1'},0}],[true]}],table),\n    {ok,'EXIT',[],[]} = erlang:match_spec_test({[a|tail]},[{{'$1'},[],[{length,'$1'}]}],table),\n    done.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string ReceiveScan = "-module(length_receive_scan).\n-export([run/0]).\nrun() ->\n    L = make(32001,[]),\n    self() ! skipped,\n    self() ! {data,L},\n    good = receive {data,First} when length(First) =:= 32001 -> good after 0 -> bad end,\n    skipped = receive Remainder1 -> Remainder1 after 0 -> missing end,\n    self() ! {data,[a|tail]},\n    timeout = receive {data,Improper} when length(Improper) > 0 -> bad after 0 -> timeout end,\n    {data,[a|tail]} = receive Remainder2 -> Remainder2 after 0 -> missing end,\n    done.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string TryMaybe = "-module(length_try_maybe).\n-export([run/0]).\nrun() ->\n    L = make(32001,[]),\n    good = try L of TryValue when length(TryValue) =:= 32001 -> good catch _:_ -> bad end,\n    good = try throw(tag) catch throw:tag when length(L) =:= 32001 -> good end,\n    good = maybe no ?= yes else ElseValue when length(L) =:= 32001 -> good end,\n    true = try apply(erlang,length,[[a|tail]]) of _ -> false catch error:badarg -> true end,\n    done.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
    public const string Values = "-module(length_values).\n-export([run/0]).\nrun() ->\n    0 = length([]),\n    4 = length([a,{b,c},[d],<<1:1>>]),\n    true = bad([a|tail]),\n    true = bad(not_a_list),\n    0 = apply(erlang,length,[[]]),\n    done.\nbad(Value) -> try apply(erlang,length,[Value]) of _ -> false catch error:badarg -> true end.\n";
    public const string ZipDynamicSizes = "-module(length_zip_dynamic_sizes).\n-export([run/0]).\nrun() ->\n    L = make(32001,[]),\n    [{tag,7}] = [{A,V} || A <- [tag] && <<_:(length(L)),V:3>> <= <<0:32001,7:3>>],\n    [{tag,ok}] = [{A,V} || A <- [tag] && #{(length(L)) := V} <- [#{32001=>ok}]],\n    done.\nmake(0,A) -> A;\nmake(N,A) -> make(N-1,[a|A]).\n";
}
